 if(version&&version!==currentVersion)throw Error('Os dados mudaram durante a consulta. Atualize novamente.');version=currentVersion;
 rows.push(...response.registros);cursor=response.proximaPagina||'';if(seen.has(cursor)&&cursor)throw Error('Paginação inválida. Atualize a consulta.');seen.add(cursor);
