  q('#od-no-results').hidden=rows.length!==0;q('#od-page-label').textContent=rows.length?'Exibindo '+(first+1)+'–'+Math.min(first+pageSize,rows.length)+' de '+rows.length:'0 resultados';q('#od-page-number').textContent=state.page+' / '+pages;
  q('[data-od="previous-page"]').disabled=state.page<=1;q('[data-od="next-page"]').disabled=state.page>=pages;
