 q('#od-period').addEventListener('change',e=>{const previous=range();state.period=e.target.value;state.page=1;if(state.period==='custom'){[state.start,state.end]=previous;q('#od-custom').elements.namedItem('start').value=state.start;q('#od-custom').elements.namedItem('end').value=state.end;}render();});
