 dash.addEventListener('click',e=>{
  const button=e.target.closest('button');if(!button)return;
  if(button.dataset.status){state.filters.status=state.filters.status===button.dataset.status?'':button.dataset.status;state.page=1;render();return;}
  if(button.dataset.remove){state.filters[button.dataset.remove]='';state.page=1;render();return;}
  if(button.dataset.customer){state.filters.customer=button.dataset.customer;state.page=1;render();return;}
  if(button.dataset.budget){budgetDetail(button.dataset.budget);return;}
  const action=button.dataset.od;
  if(action==='previous'||action==='next'){navigate(action==='next'?1:-1);return;}
  if(action==='filters'){toggleFilters(q('#od-filters').hidden);return;}
  if(action==='close-filters'){toggleFilters(false);return;}
  if(action==='reset-filters'){q('#od-filter-form').reset();return;}
  if(action==='close-detail'){q('#od-budget-detail').hidden=true;return;}
  if(action==='previous-page'||action==='next-page'){state.page+=action==='next-page'?1:-1;render();}
 });
