function table(headers,rows){return '<div class="gm-table-wrap"><table class="gm-table"><thead><tr>'+headers.map(h=>'<th>'+emEsc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function pagedTable(host,headers,rows){let page=0;const size=30;function draw(){host.innerHTML=table(headers,rows.slice(page*size,(page+1)*size))+'<div class="gm-pagination"><button type="button" data-page-table="prev" '+(page?'':'disabled')+'>Anterior</button><span>'+(rows.length?page*size+1:0)+'–'+Math.min((page+1)*size,rows.length)+' de '+rows.length+'</span><button type="button" data-page-table="next" '+((page+1)*size>=rows.length?'disabled':'')+'>Próxima</button></div>';}host.addEventListener('click',e=>{const b=e.target.closest('[data-page-table]');if(!b)return;page+=b.dataset.pageTable==='next'?1:-1;draw();});draw();}
function exportRows(headers,rows,name){const cell=v=>{const text=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"';};const csv='\uFEFF'+[headers,...rows].map(row=>row.map(cell).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportFinancial(rows){exportRows(['NF','Emissão','Cliente ERP','Cliente','Produto','Descrição','Quantidade','Unidade','TotalItem R$','Classificação','Representante','Supervisor','Gerente','Funcionário','Coordenador','Central código','Central nome'],rows.map(r=>[r.numNfv,r.date,r.erp,r.customer,r.codPro,r.descricao,r.quantidadeDecimal,r.unidade,(r.cents/100).toFixed(2).replace('.',','),r.type,r.nomeRep,r.nomeSup,r.nomeGerente,r.nomeFuncionario,r.nomeCoordenador,r.central,r.centralName]),'GBG-Faturamento-'+today()+'.csv');}
