function invoiceView(links=false){const grouped=new Map();gbgData.invoices.forEach(r=>{const record=grouped.get(r.id)||{...r,cents:0,items:0};record.cents+=r.cents;record.items=r.summary?Number(r.quantidadeItens||0):record.items+1;grouped.set(r.id,record);});const rows=[...grouped.values()].sort((a,b)=>b.date.localeCompare(a.date));detail.innerHTML='<div class="gm-view-head"><h2>'+(links?'Vínculos comerciais históricos':'Notas do Faturamento.txt')+'</h2><button type="button" id="gm-export-invoices">Exportar CSV</button></div><p>'+rows.length+' NFs · Valores dos itens que atendem aos filtros.</p><div id="gm-invoices"></div>';const headers=links?['NF / emissão','Cliente','Representante','Supervisor','Gerente','Funcionário','Coordenador']:['NF / emissão','Cliente','Itens selecionados','TotalItem','Detalhes'];pagedTable(detail.querySelector('#gm-invoices'),headers,rows.map(r=>links?[emEsc(r.numNfv)+'<small>'+emEsc(r.date)+'</small>',emEsc(r.customer),emEsc(r.nomeRep),emEsc(r.nomeSup),emEsc(r.nomeGerente),emEsc(r.nomeFuncionario),emEsc(r.nomeCoordenador)]:[emEsc(r.numNfv)+'<small>'+emEsc(r.date)+'</small>',emEsc(r.customer)+'<small>ERP '+r.erp+'</small>',r.items,emMoney(r.cents),'<button type="button" data-invoice="'+emEsc(r.id)+'">Ver itens</button>']));detail.querySelector('#gm-export-invoices').onclick=()=>exportRows(headers,rows.map(r=>links?[r.numNfv,r.customer,r.nomeRep,r.nomeSup,r.nomeGerente,r.nomeFuncionario,r.nomeCoordenador]:[r.numNfv,r.customer,r.items,(r.cents/100).toFixed(2),'']),'GBG-Notas-'+today()+'.csv');}
