async function goalView(){const requested=epoch,month=goalMonth||filters.from.slice(0,7);await loadGoals(month);if(_gAuthUser?.isAdmin){try{await ensureTeam();}catch(error){errors.Equipe=error.message;}}if(requested!==epoch||goalMonth!==month||!detail.isConnected)return;const admin=_gAuthUser?.isAdmin===true;detail.innerHTML='<h2>Metas mensais por supervisor</h2><label class="gm-month">Competência<input type="month" id="gm-goal-month" value="'+goalMonth+'" min="2000-01" max="2100-12"></label><p>Realizado do mês completo, pela supervisão gravada em cada NF do TXT. Os filtros por produto, representante e Central não reduzem a meta nem este comparativo.</p>'+(errors.Metas?'<p class="gm-warning">'+emEsc(errors.Metas)+'</p>':'')+'<div id="gm-goal-chart"></div><div id="gm-goal-results"></div>'+(admin?'<form id="gm-goal-form" class="gm-filters"><label>Supervisor<select name="sup" required><option value="">Selecione</option>'+options(rawTeam.filter(r=>r.catRep==='SUP'),'codRep','nomRep')+'</select></label><label>Meta · R$<input name="amount" inputmode="decimal" placeholder="0,00" required></label><button type="submit">Salvar meta</button><span id="gm-goal-message" role="status"></span></form>':'')+'<div id="gm-goal-history"></div>';const rows=monthlyGoals();detail.querySelector('#gm-goal-chart').innerHTML='<article class="em-chart"><h2>Meta × realizado · '+goalMonth+'</h2>'+rows.map(r=>{const max=Math.max(r.goal||0,r.actual,1);return '<div class="gm-goal-bars"><strong>'+emEsc(r.name)+'</strong><label>Meta '+(r.goal===null?'não cadastrada':emMoney(r.goal))+'</label><div class="em-bar-track"><span style="width:'+100*(r.goal||0)/max+'%;background:#a7cdc0"></span></div><label>Realizado '+emMoney(r.actual)+'</label><div class="em-bar-track"><span style="width:'+100*r.actual/max+'%;background:#199198"></span></div></div>';}).join('')+'</article>';detail.querySelector('#gm-goal-results').innerHTML=table(['Supervisor','Meta','Realizado','Atingido','Saldo para a meta','Auditoria'],rows.map(r=>[emEsc(r.name)+'<small>'+emEsc(r.code)+'</small>',r.goal===null?(goalPermission(r.code)?'Meta não cadastrada':'Meta fora da visão autorizada'):emMoney(r.goal),emMoney(r.actual),r.percentage===null?'—':r.percentage.toFixed(1)+'%',r.balance===null?'—':emMoney(r.balance),r.goal===null?'—':'<button type="button" data-goal-history="'+emEsc(r.code)+'">Histórico</button>']));detail.querySelector('#gm-goal-month').onchange=e=>{goalMonth=e.target.value;goalView();};if(admin){const form=detail.querySelector('#gm-goal-form');form.elements.namedItem('sup').onchange=e=>{const found=gbgData.goals.find(g=>M.code(g.codSup)===e.target.value);form.elements.namedItem('amount').value=found?(found.valorCentavos/100).toFixed(2).replace('.',','):'';};form.onsubmit=async e=>{e.preventDefault();const msg=detail.querySelector('#gm-goal-message'),d=new FormData(form),amount=String(d.get('amount')||'').trim();if(!/^\d+(?:\.\d{3})*(?:,\d{1,2})?$/.test(amount)){msg.textContent='Informe o valor em reais, por exemplo 50.000,00.';return;}const cents=Math.round(Number(amount.replace(/\./g,'').replace(',','.'))*100),code=d.get('sup'),previous=gbgData.goals.find(g=>M.code(g.codSup)===code),btn=form.querySelector('button');btn.disabled=true;try{await apiV5G('/management/goals',{method:'POST',body:{competencia:goalMonth,codSup:code,valorCentavos:cents,revisao:previous?.revisao||0}});reuse.delete('goals:'+goalMonth);await goalView();detail.querySelector('#gm-goal-message').textContent='Meta salva. Alteração registrada na auditoria.';}catch(error){msg.textContent=error.message;}finally{btn.disabled=false;}};}}
